package dev.kuan.kuanperion.automation.supercraft;
import dev.kuan.kuanperion.automation.*;import dev.kuan.kuanperion.automation.flight.*;import dev.kuan.kuanperion.automation.pest.*;import java.util.*;
public final class SupercraftTaskTest {
 static final long S=1_000_000_000L;static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static final SupercraftTask.Policy POLICY=new SupercraftTask.Policy(SupercraftPlanTest.RECIPE,SupercraftPlanTest.RULES,2,90,true);
 static final class Fake implements SupercraftTask.Port {
  AutomationContext ctx=new AutomationContext(1,true,true,Set.of());FlightAnchor pose=new FlightAnchor(new PestTargets.Point(100,70,0),10,20,0,SupercraftPlanTest.AIR,false);Map<Integer,ItemSnapshot> inventory=SupercraftPlanTest.inventory();boolean manual,cursorEmpty=true,dataReady=true,visible,accept=true,closeWorks=true,throwDispose;String title="Enchanted Wheat Recipe";List<String> lore=SupercraftPreviewTest.lore();int requests,commands,crafts,closes,disposes,pauses,stops;
  public AutomationContext context(){return ctx;}public SupercraftTask.Frame frame(long now){return new SupercraftTask.Frame(ctx.worldId(),now,pose,manual,cursorEmpty,true);}public Map<Integer,ItemSnapshot> inventory(){return inventory;}
  public void requestCatalog(AutomationSession.Handle h){requests++;check(h.lease().owner()==AutomationFeature.SUPERCRAFT,"fixed root demand");}public Optional<Map<String,String>> catalog(){return dataReady?Optional.of(SupercraftPreviewTest.IDS):Optional.empty();}
  public boolean recipe(AutomationSession.Handle h,SupercraftPlan.Recipe recipe,long now){commands++;return accept;}
  public MenuSnapshot menu(){if(!visible)return null;var raw=SupercraftPreviewTest.menu("Supercraft (2x crafts)",lore);var slots=new ArrayList<>(raw.slots().subList(0,54));for(int i=0;i<36;i++)slots.add(new MenuSnapshot.Slot(54+i,inventory.get(i<27?i+9:i-27),true));return new MenuSnapshot(ctx.worldId(),7,2,title,54,slots);}
  public GuardedMenuAction.Result craft(AutomationSession.Handle h,SupercraftPreview preview,long now){crafts++;check(h.lease().owner()==AutomationFeature.SUPERCRAFT&&preview.ticket().click()==MenuContract.Click.PICKUP,"no shift-max or foreign root");return accept?GuardedMenuAction.Result.SENT:GuardedMenuAction.Result.REJECTED;}
  public void closeOwnedMenu(int id){closes++;if(closeWorks){visible=false;ctx=new AutomationContext(ctx.worldId(),ctx.farmingActive(),ctx.garden(),Set.of());}}
  public void dispose(AutomationSession.Handle h){disposes++;if(throwDispose)throw new IllegalStateException("fixture cleanup failure");}
  void show(){visible=true;ctx=new AutomationContext(1,ctx.farmingActive(),true,Set.of(AutomationContext.Blocker.MENU));}
 }
 static final class H {
  Fake f=new Fake();InventoryReceipts receipts=new InventoryReceipts();CursorReceipts cursor=new CursorReceipts();AutomationSession session=new AutomationSession(new AutomationCoordinator(),f::context,()->f.pauses++,()->{f.stops++;f.ctx=new AutomationContext(f.ctx.worldId(),false,f.ctx.garden(),f.ctx.blockers());});SupercraftTask task=new SupercraftTask(session,receipts,cursor,f);long now;
  void tick(){now+=100_000_000;session.poll(now);task.tick(now);}void start(){check(task.request(POLICY,true,now),"explicit exact selected batch");for(int i=0;i<10&&f.commands==0;i++)tick();check(f.commands==1&&f.requests==1,"one typed recipe command after demand-only catalog");}
  void craft(){start();f.show();for(int i=0;i<10&&f.crafts==0;i++)tick();check(f.crafts==1&&task.state()==SupercraftTask.State.WAIT_RESULT,"one guarded attempt");}
  void result(boolean server,boolean emptyCursor){for(int i=9;i<14;i++){f.inventory.put(i,SupercraftPlanTest.AIR);if(server)receipts.observe(1,0,i,f.inventory.get(i));}f.inventory.put(14,SupercraftPlanTest.item("ENCHANTED_WHEAT",2,false,""));if(server)receipts.observe(1,0,14,f.inventory.get(14));if(emptyCursor)cursor.observe(1,7,SupercraftPlanTest.AIR,now+1);}
 }
 public static void main(String[]args){
  H h=new H();check(!h.task.request(SupercraftTask.Policy.defaults(),true,0)&&h.f.requests==0&&!h.session.active(),"defaults never authorize catalog/command/craft");h.f.inventory.put(9,SupercraftPlanTest.AIR);check(!h.task.request(POLICY,true,0)&&h.f.requests==0,"preflight materials before acquiring Farming or querying");
  h=new H();h.start();check(h.session.holdsFarming()&&h.f.pauses==1,"original revocable Farming hold");h.task.cancel(h.now);check(h.f.stops==1&&h.f.closes==0&&h.f.disposes==1&&!h.session.active(),"cancel stops original Farm, never closes foreign GUI or guesses repair");
  h=new H();h.f.dataReady=false;check(h.task.request(POLICY,true,0),"data wait starts only under root");for(int i=0;i<130&&h.task.active();i++)h.tick();check(h.task.state()==SupercraftTask.State.TIMED_OUT&&h.f.commands==0&&h.f.stops==1,"catalog timeout performs no command/craft");
  h=new H();h.start();for(int i=0;i<90&&h.task.active();i++)h.tick();check(h.task.state()==SupercraftTask.State.TIMED_OUT&&h.f.crafts==0&&h.f.commands==1,"unknown/missing menu does not resend recipe");
  h=new H();h.start();h.f.lore=new ArrayList<>(SupercraftPreviewTest.lore());h.f.lore.set(1,"320x from Sacks");h.f.show();for(int i=0;i<90&&h.task.active();i++)h.tick();check(h.f.crafts==0&&h.f.closes==0&&h.f.stops==1,"storage allocation not authorized by enough inventory and cannot silently fall back");
  h=new H();h.craft();h.result(false,true);h.tick();check(h.task.confirmedOutput()==0&&h.f.crafts==1,"predicted craft never succeeds or repeats");h.result(true,true);h.tick();check(h.task.confirmedOutput()==2&&h.f.closes==0,"actual receipts first, exact owned close later");h.tick();check(h.task.state()==SupercraftTask.State.COMPLETE&&!h.session.active()&&!h.session.holdsFarming()&&h.f.ctx.farmingActive()&&h.f.stops==0&&h.f.closes==1&&h.f.disposes==1,"only confirmed batch and safe unchanged original pose/tool allow release/resume");
  h=new H();h.craft();h.result(true,false);for(int i=0;i<160&&h.task.active();i++)h.tick();check(h.task.state()==SupercraftTask.State.TIMED_OUT&&h.f.crafts==1&&h.f.closes==0&&h.f.stops==1,"no cursor acknowledgement => stop, no retry/repair/auto close");
  h=new H();h.craft();h.f.visible=false;h.f.ctx=new AutomationContext(1,true,true,Set.of());h.tick();check(!h.task.active()&&h.f.stops==1&&h.f.closes==0,"unproven server/local menu disappearance cannot resume Farming");
  h=new H();h.craft();h.result(true,true);h.f.manual=true;h.tick();check(h.task.confirmedOutput()==0&&!h.task.active()&&h.f.closes==0,"manual takeover beats complete delayed receipts");
  h=new H();h.craft();h.result(true,true);h.f.pose=new FlightAnchor(new PestTargets.Point(101,70,0),10,20,0,SupercraftPlanTest.AIR,false);h.tick();check(!h.task.active()&&h.f.closes==0&&h.f.stops==1,"unexplained position change cannot resume original farming route");
  h=new H();h.craft();h.result(true,true);h.tick();h.f.closeWorks=false;h.tick();check(h.task.state()==SupercraftTask.State.FAILED&&h.f.stops==1&&h.f.crafts==1&&h.f.closes==1,"failed native close never retries or releases farming as successful");
  h=new H();h.f.ctx=new AutomationContext(1,false,false,Set.of());check(!h.task.request(POLICY,false,0)&&h.task.request(POLICY,true,0)&&!h.session.holdsFarming(),"automatic only-Farming gate independent from explicit standalone SkyBlock request");h.task.cancel(1);check(h.f.stops==0,"never invent a Farm to stop/resume");
  var tooSmall=new SupercraftPlan.Rules(SupercraftPlanTest.RULES.outputs(),SupercraftPlanTest.RULES.ingredients(),64,159,64,Set.of());check(!new SupercraftTask.Policy(SupercraftPlanTest.RECIPE,tooSmall,1,90,true).configured(),"statically impossible input budget cannot be presented as configured");
  h=new H();h.craft();h.result(true,true);h.f.ctx=new AutomationContext(1,false,true,Set.of(AutomationContext.Blocker.MENU));h.tick();check(!h.task.active()&&h.f.stops==0&&h.f.closes==0&&!h.f.ctx.farmingActive(),"manual Farm off cannot be rearmed by late proof");
  h=new H();h.craft();h.session.invalidate();h.f.visible=false;h.f.ctx=new AutomationContext(1,true,true,Set.of());var newer=h.session.begin(AutomationFeature.AUTO_SELL,h.now+1,60*S);check(newer!=null,"new owner fixture");h.task.tick(h.now+2);check(h.session.isCurrent(newer)&&h.f.closes==0,"stale task cleanup cannot cancel or close a new owner's menu");h.session.cancel(h.now+3);
  h=new H();h.craft();h.f.ctx=new AutomationContext(2,true,true,Set.of(AutomationContext.Blocker.MENU));h.tick();check(!h.task.active()&&h.f.closes==0&&h.f.crafts==1,"world invalidation wins without retry or stale GUI close");
  h=new H();h.start();h.f.accept=false;h.f.show();h.tick();check(h.task.state()==SupercraftTask.State.FAILED&&h.f.crafts==1&&h.f.closes==0&&h.f.stops==1,"guarded native refusal is terminal without retry");
  h=new H();h.craft();h.result(true,true);h.tick();h.f.throwDispose=true;h.tick();check(h.task.state()==SupercraftTask.State.FAILED&&h.f.stops==1&&!h.f.ctx.farmingActive()&&!h.session.active(),"cleanup failure must stop the held original Farm before any successful release");
  System.out.println("SupercraftTaskTest: PASS (exact batch/policy, one root/catalog/recipe/native attempt, preview source gate, server proof, unchanged origin/owned close before Farming release, manual/world/timeout uncertainty)");
 }
}
